 values.forEach((v,i)=>{const el=$('#demand'+i),size=Math.min(1,Math.abs(v)/(i===0?2000:1500))*50;el.style.height=size+'%';el.style.top=v<0?'50%':'auto';el.style.bottom=v>=0?'50%':'auto';el.parentElement.parentElement.title=['Residential','Commercial','Industrial'][i]+' demand: '+v;});
