function setGridSpacing(value){gridSpacing=clamp(Math.round(Number.isFinite(value)?value:4),2,24);$('#gridSpacing').value=gridSpacing;rememberDrawSettings();paint();}

function setOverlay(mode){
 if(!(mode in OVERLAYS))return;mapView=mode;buildPalette?.mapView(mode!=='none');stroke=null;panGesture=null;
 $('#touchBuild').hidden=mode!=='none';$('#touchPan').setAttribute('aria-pressed',mode!=='none'||touchMode==='pan');$('#touchBuild').setAttribute('aria-pressed',mode==='none'&&touchMode==='build');$('#overlay').value=mode;$('#tools').hidden=mode!=='none';$('#overlayTools').hidden=mode==='none';$('.drawing-controls').hidden=mode!=='none';$('.tools .section-title').textContent=mode==='none'?'BUILD':'MAP OVERLAYS';$('#view').textContent=mode==='none'?'MAP VIEW':'CITY VIEW';
 document.querySelectorAll('[data-overlay]').forEach(button=>{const active=button.dataset.overlay===mode;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',active);});paint();
}

function overlayLegend(){if(mapView==='water'||(mapView==='none'&&selected===40))return (pipeFlowText(city,cursor.x,cursor.y)||'')+' · '+'UNDERGROUND · blue: pipe reach · green plots: supplied · amber plots: pump capacity shortage · grey: no source · reach 3 · cyan arrows: water → buildings · amber: sewage → pumps · dashed: proposed · capacity applies';
 if(mapView==='none')return placementCoverageLegend(city,selected,cursor.x,cursor.y);
 if(mapView==='railTraffic'||mapView==='airTraffic')return placementCoverageLegend(city,mapView==='railTraffic'?2:12,cursor.x,cursor.y);if(mapView==='growthRate'){const n=cityGrowthRateAt(city,cursor.x,cursor.y);return 'Growth / decline · index '+(n>=0?'+':'')+n+' · green positive / red negative · 8×8 areas; includes development attempts';}
 if(mapView==='wind')return windDescription(city.climate)+' · '+Math.round(city.climate.direction)+'° · arrows show where pollution travels';
 if(['health','unemployment','education'].includes(mapView)){const f=socialFields(city),i=cursor.y*W+cursor.x;return OVERLAYS[mapView]+(f.mask[i]?' '+f[mapView][i]+'/100':' · no residential data here')+(mapView==='unemployment'?' · green employed / red jobless':' · red low / green high');}
 if(mapView==='sewage')return 'Sewage: brown pipes carry waste · brown water is contaminated · backlog '+(city.civic.sewageBacklog||0);
 if(mapView==='crime'||mapView==='policeCoverage'){
  const local=city.policeEffectAt(cursor.x,cursor.y),station=local.station?' · station '+(local.station.powered?'powered':'unpowered')+', '+(local.station.road?'road access':'no road access'):'';
  return (mapView==='crime'?'Crime '+local.crime+'/250 · police '+local.coverage:'Police coverage '+local.coverage+' · funding strength '+Math.round(local.strength/10)+'% · effectiveness '+local.effectiveness+'×')+station+' · '+(paused?'paused; resume to update':'next refresh in '+local.nextUpdate+' simulation steps');
 }
 return OVERLAYS[mapView]+(mapView==='power'?' · red: unpowered / green: powered':' · green: low / red: high');
}


function refreshCityWarning(){let lesson=city.scenario==='PracticeCity'?city.practiceTutorial.pendingId:null;if(!showWarnings&&lesson!==null){city.dismissNotice(practiceNotice(lesson));lesson=null;}const message=lesson!==null?practiceNotice(lesson):city.notices[0]||'',warning=$('#cityWarning');$('#readPracticeLesson').hidden=lesson===null;warning.hidden=!showWarnings||!message||city.noticeIsDismissed(message);$('#cityWarningText').textContent=message;if(warning.hidden){clearTimeout(warningTimer);warningTimer=null;warningToken=null;return;}if(warningToken?.city===city&&warningToken.message===message)return;clearTimeout(warningTimer);const token={city,message};warningToken=token;warningTimer=setTimeout(()=>{if(warningToken!==token)return;if(city===token.city){city.dismissNotice(token.message);warning.hidden=true;}warningToken=null;warningTimer=null;},3000);}


function panBlueprintAtEdge(dt){
 if(!stroke?.pointer)return;const r=canvas.getBoundingClientRect(),p=stroke.pointer,edge=14,amount=dt*.018/zoom;
 const dx=p.clientX<r.left+edge?-1:p.clientX>r.right-edge?1:0,dy=p.clientY<r.top+edge?-1:p.clientY>r.bottom-edge?1:0;
 const x=clamp(camera.x+dx*amount,0,Math.max(0,W-120/zoom)),y=clamp(camera.y+dy*amount,0,Math.max(0,H-75/zoom));
 if(x!==camera.x||y!==camera.y){camera.x=x;camera.y=y;pointer(p,true);}
}

function updatePlacementTooltip(){
 const el=$('#placementTooltip');if(!el)return;
 const r=canvas.getBoundingClientRect(),p=placementPointer,inside=p&&p.x>=r.left&&p.x<=r.right&&p.y>=r.top&&p.y<=r.bottom;
 if(!city||!p||(!inside&&!stroke)||mapView!=='none'||panGesture||selected<0||selected>=build.buildings.length||!$('#modal').classList.contains('hidden')){el.hidden=true;return;}
 const plan=stroke?stroke.plan:hoverPlanCache||hoverPlacementPlan();if(!plan){el.hidden=true;return;}
 el.hidden=false;el.className=plan.ok?'valid':'invalid';el.textContent=plan.ok?'$'+plan.cost.toLocaleString()+(plan.anchors?' · '+plan.anchors.length+' placements':'')+(plan.skipped?' · '+plan.skipped+' skipped':''):((plan.reason||'Cannot place here.')+(plan.reason==='Insufficient funds.'?'\nCost: $'+plan.cost.toLocaleString():''));
 if(selected===46||selected===47)el.textContent+='\nElevation '+city.elevation[cursor.y*W+cursor.x]+' → '+(city.elevation[cursor.y*W+cursor.x]+(selected===46?1:-1));
 const box=el.getBoundingClientRect(),x=clamp(p.x+16,8,Math.max(8,innerWidth-box.width-8));let y=p.type==='touch'?p.y-box.height-28:p.y+20;
 if(y+box.height>innerHeight-72)y=p.y-box.height-18;el.style.left=x+'px';el.style.top=clamp(y,8,Math.max(8,innerHeight-box.height-72))+'px';
}

function readDrawPreferences(){try{const p=JSON.parse(localStorage.getItem('simcity.drawPreferences.v1')||'null');if(p&&p.version===1&&p.tools&&typeof p.tools==='object')return p;}catch{}return {version:1,lastTool:1,tools:{}};}
function readWarningPreference(){try{return localStorage.getItem('simcity.showWarnings')!=='false';}catch{return true;}}
function currentDrawSettings(){return {mode:drawMode,gridSpacing,blockColumns,blockRows,blockCourtyard,blockRoads,autoDemolish,replaceRoadOnly,fillAvailable};}
function rememberDrawSettings(){if(selected<0||selected>=build.buildings.length)return;savedDrawPreferences.tools[selected]=currentDrawSettings();savedDrawPreferences.lastTool=selected;try{localStorage.setItem('simcity.drawPreferences.v1',JSON.stringify(savedDrawPreferences));}catch{}}
function selectBuildTool(tool,{rememberCategory=true}={}){
 if(tool!==-2&&(!Number.isInteger(tool)||tool<0||tool>=build.buildings.length||!build.buildings[tool]))tool=1;$('#inspectTool')?.classList.toggle('selected',tool===-2);
 const firstSelection=selected===-1;rememberDrawSettings();selected=tool;buildPalette?.reveal(tool,!firstSelection&&rememberCategory);const s=savedDrawPreferences.tools[tool]||{},modes=['freehand','line','rectangle','filled','grid','blocks'];drawMode=modes.includes(s.mode)?s.mode:'line';if(drawMode==='blocks'&&(tool<5||tool>7))drawMode='line';
 gridSpacing=clamp(Math.trunc(s.gridSpacing)||4,2,24);blockColumns=clamp(Math.trunc(s.blockColumns)||3,1,12);blockRows=clamp(Math.trunc(s.blockRows)||3,1,12);blockCourtyard=s.blockCourtyard!==false;blockRoads=!!s.blockRoads;autoDemolish=!!s.autoDemolish;replaceRoadOnly=!!s.replaceRoadOnly;fillAvailable=!!s.fillAvailable;stroke=null;
 syncDrawControls();rememberDrawSettings();updateTools();paint();
}
function syncDrawControls(){
 if(!$('#drawMode'))return;$('#drawMode').value=drawMode;$('#gridSpacing').value=gridSpacing;$('#blockColumns').value=blockColumns;$('#blockRows').value=blockRows;$('#blockCourtyard').checked=blockCourtyard;$('#blockRoads').checked=blockRoads;$('#autoDemolish').checked=autoDemolish;$('#replaceRoadOnly').checked=replaceRoadOnly;$('#replaceRoadOnlyLabel').hidden=selected!==2;$('#fillAvailable').checked=fillAvailable;$('#gridSpacingLabel').hidden=drawMode!=='grid';$('#blockSettings').hidden=drawMode!=='blocks';$('#fillAvailableLabel').hidden=false;
}
